content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-18-carpool-002

=== 用户原始指令 (query.txt) ===
整个拼车清单能打勾，显示200米，能看天气，看到已连接

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "整个拼车清单能打勾，显示200米，能看天气，看到已连接",
  "size": "2x4",
  "eventCandidates": [],
  "dataModelSchema": {
    "carpool": {
      "title": {
        "type": "string",
        "description": "拼车出行卡片标题。",
        "sampleValue": "拼车出行"
      },
      "distanceText": {
        "type": "string",
        "description": "距离上车点或集合点的展示文本。",
        "sampleValue": "200米"
      },
      "distanceCaption": {
        "type": "string",
        "description": "距离信息的短说明。",
        "sampleValue": "距上车点"
      },
      "connectionText": {
        "type": "string",
        "description": "当前拼车服务或设备连接状态。",
        "sampleValue": "已连接"
      },
      "checklistLabel": {
        "type": "string",
        "description": "可勾选的拼车清单名称。",
        "sampleValue": "拼车清单"
      },
      "checklistDone": {
        "type": "boolean",
        "description": "整个拼车清单是否已勾选确认。",
        "sampleValue": true
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询所在区县名称。",
            "sampleValue": "南山"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本。",
            "sampleValue": "26°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象。",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级。",
            "sampleValue": "优"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_car.png",
      "description": "汽车/打车彩色图标，适合表达拼车、上车点和出行状态。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标，适合表达当前多云天气和出行天气概览。"
    }
  ]
}

